mapper.select:
select cont.* from ( select contract_id as contractId, charge_subject_version as chargeSubjectVersion, payment_schedule_version as paymentScheduleVersion, -- settle_subject_id as settleSubjectId, -- settle_subject_name as settleSubjectName, ver as ver FROM contract_charge where contract_id IN
#{ids}
order by ver desc )as con GROUP BY con.contractId

select
ct.id as 'contractId',
ct.contract_code as 'contractCode',
ct.direction ,
ct.contract_template_business_type as 'businessType',
ct.transport_mode as 'transportMode'
FROM contract ct

    IFNULL(ct.is_delete, 0) != 1
    and ct.contract_type = 2961010
    and ct.valid_start_date  <  #{dispatchTime}
    and ct.valid_end_date  >=  #{dispatchTime}


        and ct.trustor_company_id = #{trustorCompanyId}


        and ct.carrier_company_id = #{carrierCompanyId}


        and ct.agent_company_id = #{agentCompanyId}


        and ct.direction = #{direction,jdbcType=BIGINT}


        and ct.contract_template_business_type = #{contractTemplateBusinessType,jdbcType=BIGINT}


        and ct.transport_mode = #{transportMode,jdbcType=BIGINT}



order by ct.create_time desc

SELECT id FROM contract
WHERE   document_type = #{documentType}
AND create_time   >=  #{startTime}
AND create_time  <  #{endTime}

SELECT ct.contract_code 'contractCode', ct.title 'title', ct.trustor_company_id 'trustorCompanyId', ct.trustor_company_name 'trustorCompanyName', ct.carrier_company_id 'carrierCompanyId', ct.carrier_company_name 'carrierCompanyName', ct.agent_company_id 'agentCompanyId', ct.agent_company_name 'agentCompanyName', ct.valid_start_date 'validStartDate', ct.valid_end_date 'validEndDate', ct.contract_date 'contractDate', a.file_id 'fileId' FROM contract ct LEFT JOIN contract_attach a ON ct.id = a.contract_id
IFNULL(ct.is_delete, 0) != 1 and ct.contract_type = 2961010
and ( ct.trustor_company_id in
#{item}
or ct.carrier_company_id in
#{item}
or ct.agent_company_id in
#{item}
)
and date_format(ct.contract_date,'%Y-%m-%d') >= date_format(#{startDate},'%Y-%m-%d')
and date_format(ct.contract_date,'%Y-%m-%d') <= date_format(#{endDate},'%Y-%m-%d')
order by ct.create_time desc

select ct.id as 'id', ct.contract_code as 'contractCode', ct.title as 'title', ct.valid_start_date as 'validStartDate', ct.valid_end_date as 'validEndDate', ct.contract_date as 'contractDate', ct.trade_time as 'tradeTime', ct.creater as 'createrId', ct.create_time as 'createTime', ct.stamp_photo_id as 'stampPhotoId', ct.contract_type as 'contractType', ct.is_order as 'isOrder', ct.order_id as 'orderId', ct.dispatch_batch_id as 'dispatchBatchId', ct.modifier as 'modifier' , ct.modify_time as 'modifyTime', ct.ver as 'ver', ct.trustor_company_id as 'trustorCompanyId', ct.trustor_company_name as 'trustorCompanyName', ct.carrier_company_id as 'carrierCompanyId', ct.carrier_company_name as 'carrierCompanyName', ct.trustor_contact_name as 'trustorContactName', ct.trustor_contact_mobile as 'trustorContactMobile', ct.carrier_contact_name as 'carrierContactName', ct.carrier_contact_mobile as 'carrierContactMobile', ct.contract_template_id as 'contractTemplateId', ct.contract_template_name as 'contractTemplateName', ct.compile_side_id as 'compileSideId', ct.strategy_id as 'strategyId', ct.strategy_name as 'strategyName', ct.is_delete as 'isDelete', ct.ec_contract_path as 'ecContractPath', ct.ec_contract_pdf_id as 'ecContractPdfId', ct.ec_contract_result_code as 'ecContractResultCode', ct.ec_contract_result_desc as 'ecContractResultDesc', ct.ec_contract_create_time as 'ecContractCreateTime', ct.ec_contract_esign_file_id as 'ecContractEsignFileId', ct.ec_contract_esign_flow_id as 'ecContractEsignFlowId', ct.trustor_sign_status as 'trustorSignStatus', ct.contract_measuring_collection as 'contractMeasuringCollection', ct.contract_goods_collection as 'contractGoodsCollection', ct.carrier_sign_status as 'carrierSignStatus', ct.parent_contract_id as 'parentContractId', ct.document_id as 'documentId', ct.document_code as 'documentCode', ct.document_type as 'documentType', ct.contract_price as 'contractPrice', ct.direction as 'direction', ct.plat_company_id as 'platCompanyId', ct.contract_template_business_type as 'contractTemplateBusinessType', ct.agent_company_id as 'agentCompanyId', ct.agent_company_name as 'agentCompanyName', ct.agent_contact_name as 'agentContactName', ct.agent_contact_mobile as 'agentContactMobile', ct.agent_sign_status as 'agentSignStatus', ct.transport_mode as 'transportMode', ct.vehicle_code as 'vehicleCode' FROM contract ct
and ct.id = #{param.id}
and ct.document_id = #{param.documentId}
and ct.document_id in
#{id}
and ct.dispatch_batch_id = #{param.dispatchBatchId}
and ct.is_delete = #{param.isDelete}
order by ct.create_time desc

select ct.id as 'contractId', ct.contract_code as 'contractCode', ct.title as 'title', ct.valid_start_date as 'validStartDate', ct.valid_end_date as 'validEndDate', ct.trade_time as 'tradeTime', ct.contract_date as 'contractDate', ct.creater as 'createrId', ct.create_time as 'createTime', ct.contract_type as 'contractType', ct.document_id as 'documentId', ct.document_code as 'documentCode', ct.document_type as 'documentType', ct.contract_price as 'contractPrice', ct.modifier as 'modifier' , ct.modify_time as 'modifyTime', ct.ver as 'ver', ct.trustor_company_id as 'trustorCompanyId', ct.carrier_company_id as 'carrierCompanyId', ct.agent_company_id as 'agentCompanyId', ct.compile_side_id as 'compileSideCompanyId', ct.contract_template_id as 'contractTemplateId', ct.contract_template_name as 'contractTemplateName', ct.contract_template_business_type as 'businessType', ct.is_delete as 'isDelete', ct.ec_contract_pdf_id as 'ecContractPdfId', ct.ec_contract_result_code as 'ecContractResultCode', ct.ec_contract_result_desc as 'ecContractResultDesc', ct.trustor_sign_status as 'trustorSignStatus', ct.carrier_sign_status as 'carrierSignStatus', ct.agent_sign_status as 'agentSignStatus', ct.ec_contract_create_time as 'ecContractCreateTime', ct.trustor_company_name as 'trustorCompanyName', ct.carrier_company_name as 'carrierCompanyName', ct.agent_company_name as 'agentCompanyName', ct.creater as 'creater', ct.contract_goods_collection as 'contractGoodsCollection', ct.contract_measuring_collection as 'contractMeasuringCollection', ct.transport_mode as 'transportMode', if(ct.transport_mode=1041030,'船运','汽运') as 'transportModeDesc', ct.parent_contract_id as 'parentContractId' FROM contract ct
IFNULL(ct.is_delete, 0) != 1 and (ct.document_type <> 1133000 or ct.document_type is NULL)
and (ct.parent_contract_id = '0' or ct.parent_contract_id is null)
and ct.parent_contract_id in
#{id}
and ct.contract_code = #{contractListQry.contractCode}
and instr(ct.trustor_company_name, #{contractListQry.trustorCompanyName,jdbcType=CHAR})
and instr(ct.carrier_company_name, #{contractListQry.carrierCompanyName,jdbcType=CHAR})
and instr(ct.agent_company_name, #{contractListQry.agentCompanyName,jdbcType=CHAR})
and ((date_format(ct.valid_start_date,'%Y-%m-%d') >= date_format(#{contractListQry.startDate,jdbcType=VARCHAR},'%Y-%m-%d')))
and ((date_format(ct.valid_end_date,'%Y-%m-%d') <= date_format(#{contractListQry.endDate,jdbcType=VARCHAR},'%Y-%m-%d')))
and ct.create_time >= #{contractListQry.createTimeStart}
and ct.create_time <= #{contractListQry.createTimeEnd}
and ct.trustor_sign_status = #{contractListQry.trustorSignStatus,jdbcType=BIGINT}
and ct.carrier_sign_status = #{contractListQry.carrierSignStatus,jdbcType=BIGINT}
and ct.agent_sign_status = #{contractListQry.agentSignStatus,jdbcType=BIGINT}
and ct.contract_type = #{contractListQry.contractType,jdbcType=BIGINT}
and ct.document_type = #{contractListQry.documentType,jdbcType=BIGINT}
and ct.contract_template_business_type = #{contractListQry.businessType,jdbcType=BIGINT}
and ct.contract_code = #{contractListQry.dispatchBatchCode,jdbcType=VARCHAR}
and ct.id = #{contractListQry.contractId}
and ct.contract_type in
#{item}
and (ct.trustor_company_id in
#{item}
or ct.carrier_company_id in
#{item}
or ct.agent_company_id in
#{item}
or ct.compile_side_id in
#{item}
or ct.plat_company_id in
#{item}
)
order by ct.create_time desc
